/**
 * Registers the service worker (rebuild increment 21). Imported only by the
 * real app's entry point (src/main.tsx): the clickable demo and the tests
 * never load it.
 *
 * The service worker is generated by vite-plugin-pwa (see src/lib/pwa/config.ts) and
 * exists only in production builds. It is not registered on the public
 * signing page or the public ITP generator, so external signers and
 * anonymous visitors never get the app's files stored on their device.
 */
import { registerSW } from "virtual:pwa-register"

import {
  isPublicOnlinePage,
  reportOfflineReady,
  reportUpdateAvailable,
} from "./state"

/** How often an open app checks for a newly published version. */
const UPDATE_CHECK_MS = 60 * 60 * 1000

export function registerServiceWorker(): void {
  if (typeof window === "undefined" || !("serviceWorker" in navigator)) return
  if (isPublicOnlinePage(window.location.pathname)) return

  const updateSW = registerSW({
    onNeedRefresh() {
      reportUpdateAvailable(() => updateSW(true))
    },
    onOfflineReady() {
      reportOfflineReady()
    },
    onRegisteredSW(_url, registration) {
      if (!registration) return
      // Field devices keep the app open for days: look for a new version
      // every hour, but only when there is signal.
      window.setInterval(() => {
        if (navigator.onLine) void registration.update().catch(() => {})
      }, UPDATE_CHECK_MS)
    },
    onRegisterError(error) {
      // The app keeps working online without it.
      console.warn("The app could not be installed for offline use", error)
    },
  })
}
